-- 18-seed-dia-gioi-hanh-chinh.sql
-- Data List dia gioi hanh chinh (34 tinh/thanh, 3321 phuong/xa). Nguon: test_files/Danh-muc-Phuong-xa_moi.xlsx
-- dm_tinh: {ma_tinh, ten_tinh, vung_mien}; dm_xa: {ten_xa} + parent_row_id -> dm_tinh

SET @dm_tinh_id = (SELECT id FROM data_lists WHERE name = 'dm_tinh');
SET @dm_xa_id = (SELECT id FROM data_lists WHERE name = 'dm_xa');


